# 4.6 — tiến trình, tác vụ hẹn giờ, PowerShell: 4688, 4698/4702, 4103/4104 — mẫu công khai (security_big_sample.evtx, many-events-security.evtx Win7,
# tc/task-4698.evtx + tc/task-4624-4702.evtx (EVTX-ATTACK-SAMPLES), tc/ps-tai-payload.evtx (EVTX-to-MITRE-Attack), tc/ps-obfuscation.evtx (DeepBlueCLI, Invoke-Obfuscation)).
@ps evtx-rec mau/dbc-many-events-security.evtx | ConvertFrom-Json | Where-Object { $_.id -eq 4688 -and $_.data.NewProcessName -like '*\cmd.exe' -and $_.data.CommandLine } | Select-Object -First 1 | ForEach-Object { $_.data | Format-List }
@ps foreach ($f in 'mau/dbc-many-events-security.evtx','mau/security_big_sample.evtx','mau/2-system-Security-dirty.evtx') { $e = evtx-rec $f 2>$null | ConvertFrom-Json | Where-Object id -eq 4688; '{0,-34} 4688: {1,5}   có trường CommandLine: {2,5}   trong đó rỗng: {3,4}' -f $f, $e.Count, @($e | Where-Object { $_.data.PSObject.Properties.Name -contains 'CommandLine' }).Count, @($e | Where-Object { $_.data.PSObject.Properties.Name -contains 'CommandLine' -and -not $_.data.CommandLine }).Count }
@ps evtx-rec mau/2-system-Security-dirty.evtx 2>$null | ConvertFrom-Json | Where-Object id -eq 4688 | Group-Object { '{0} <- {1}' -f ($_.data.NewProcessName -split '\\')[-1], ($_.data.ParentProcessName -split '\\')[-1] } | Sort-Object Count -Descending | Select-Object -First 6 Count,@{n='Con <- Cha';e={$_.Name}} | Format-Table -AutoSize
@ps evtx-rec tc/task-4698.evtx | ConvertFrom-Json | Where-Object id -eq 4698 | ForEach-Object { '{0}  {1} tạo tác vụ {2}' -f $_.t.ToString('s'), $_.data.SubjectUserName, $_.data.TaskName; ([xml]$_.data.TaskContent).Task | ForEach-Object { 'Chạy: ' + $_.Actions.Exec.Command; 'Lặp: ' + $_.Triggers.TimeTrigger.Repetition.Interval; 'Dưới quyền: ' + $_.Principals.Principal.UserId } }
@ps evtx-rec tc/task-4624-4702.evtx | ConvertFrom-Json | Where-Object id -in 4624,4702 | ForEach-Object { '{0}  {1}  {2,-17} type={3,-2} ip={4,-14} logonId={5}' -f $_.t.ToString('HH:mm:ss.fff'), $_.id, ($_.data.TargetUserName + $_.data.TaskName), $_.data.LogonType, $_.data.IpAddress, $(if ($_.id -eq 4624) { $_.data.TargetLogonId } else { $_.data.SubjectLogonId }) } | Select-Object -First 4
@ps evtx-rec tc/task-4624-4702.evtx | ConvertFrom-Json | Where-Object id -eq 4702 | ForEach-Object { ([xml]$_.data.TaskContentNew).Task | ForEach-Object { 'Chạy: {0} {1}' -f $_.Actions.Exec.Command, $_.Actions.Exec.Arguments; 'Dưới quyền: {0}, RunLevel: {1}' -f $_.Principals.Principal.UserId, $_.Principals.Principal.RunLevel } }
@ps evtx-rec tc/ps-tai-payload.evtx | ConvertFrom-Json | ForEach-Object { '{0}  {1}  {2,-7}  {3}' -f $_.t.ToString('HH:mm:ss'), $_.id, $_.muc, $(if ($_.id -eq 4104) { $_.data.ScriptBlockText } else { ($_.data.Payload -split "`r?`n")[0] }) }
@ps evtx-rec tc/ps-obfuscation.evtx | ConvertFrom-Json | Group-Object muc | Select-Object Count,Name | Format-Table -AutoSize
@ps evtx-rec tc/ps-obfuscation.evtx | ConvertFrom-Json | Select-Object -First 1 | ForEach-Object { $s = $_.data.ScriptBlockText; $s.Substring(0, 110); '...'; $so = [regex]::Matches($s, '\d+') | ForEach-Object { [int]$_.Value } | Where-Object { $_ -ge 32 -and $_ -lt 127 }; 'Giải mã: ' + (-join ($so | ForEach-Object { [char]$_ })) }
